/**
 * 五上 · 單元 4：公倍數與公因數（翰林版）
 * 2026-08-07
 *
 * 依賴單元 2（倍數與因數）。
 *
 * 設計重點：小孩在這個單元最常見的錯不是「不會算」，是「不知道什麼時候該用哪一個」。
 * 所以最後一段特別花篇幅在「分組 → 最大公因數」「重複遇到 → 最小公倍數」的判斷，
 * 而不是只練計算。
 */

'use strict';

(function () {
  const { ChoiceQuiz, CommonGrid, VennFactors, PeriodSync, SortBuckets } = window.G5;

  const unit = {
    id: 'g5-u04-common',
    grade: 5,
    semester: '上',
    order: 4,
    title: '單元 4　公倍數與公因數',
    subtitle: '兩個數共同擁有的那些數',
    icon: '🔗',
    estimatedMinutes: 30,
    objectives: [
      '知道公因數就是「兩個數共同的因數」',
      '會找出兩個數的所有公因數，並找出最大公因數',
      '知道公倍數就是「兩個數共同的倍數」',
      '會找出最小公倍數',
      '遇到應用題時，判斷得出該用最大公因數還是最小公倍數',
    ],
    wrapUp: '最大公因數會用在下一個階段的「約分」，最小公倍數會用在「通分」和異分母分數加減。這裡打穩了，分數運算就會輕鬆很多。',

    sections: [
      /* ── 1. 情境：分組 ───────────────────────── */
      {
        heading: '兩個班要分成一樣大的小組',
        blocks: [
          {
            type: 'text',
            text: '五年一班有 12 人，五年二班有 18 人。老師想把兩班都分成人數一樣多的小組，而且每一組都要剛好分完、不能有人落單。',
          },
          {
            type: 'text',
            text: '每組 2 人可以嗎？12 ÷ 2 = 6 組、18 ÷ 2 = 9 組，兩邊都剛好，可以。每組 4 人呢？12 ÷ 4 = 3 組沒問題，但 18 ÷ 4 = 4 剩 2，二班會剩 2 個人，不行。',
          },
          {
            type: 'callout', icon: '🤔', title: '想一想',
            text: '「每組幾人」必須同時是 12 的因數、也是 18 的因數才行。這種兩邊都符合的數，就叫做「公因數」。',
          },
        ],
      },

      /* ── 2. 找公因數 ─────────────────────────── */
      {
        heading: '把兩個數的因數畫在同一張圖上',
        blocks: [
          {
            type: 'text',
            text: '下面的方格用顏色標出 12 的因數和 18 的因數。注意看有些格子兩個顏色都有——那就是公因數。',
          },
          { type: 'component', build: () => new CommonGrid({ a: 12, b: 18, max: 18, mode: 'factor' }) },
          {
            type: 'callout', icon: '🔑', title: '公因數',
            text: '12 和 18 的公因數是 1、2、3、6。回到剛才的問題：每組可以是 1 人、2 人、3 人或 6 人，這四種分法兩班都能剛好分完。',
          },
        ],
      },

      /* ── 3. 最大公因數 ───────────────────────── */
      {
        heading: '最大公因數：組別最少、每組最多人',
        blocks: [
          {
            type: 'text',
            text: '如果老師希望「每組人數盡量多」，那就要挑公因數裡最大的那個。這個數叫做「最大公因數」。',
          },
          { type: 'component', build: () => new VennFactors({ a: 12, b: 18 }) },
          {
            type: 'callout', icon: '📌', title: '答案',
            text: '12 和 18 的最大公因數是 6。每組 6 人時，一班分成 2 組、二班分成 3 組，人數最多且剛好分完。',
          },
          { type: 'text', text: '換你找：在下面的方格中，把 16 和 24 的公因數全部點出來。' },
          { type: 'component', build: () => new CommonGrid({ a: 16, b: 24, max: 24, mode: 'factor', interactive: true }) },
        ],
      },

      /* ── 4. 情境：公車 ───────────────────────── */
      {
        heading: '兩班公車，什麼時候會同時發車？',
        blocks: [
          {
            type: 'text',
            text: '公車站有兩條路線。紅線每 4 分鐘發一班，藍線每 6 分鐘發一班。早上 8 點整兩班同時發車後，下一次會在什麼時候再度同時發車？',
          },
          {
            type: 'component',
            build: () => new PeriodSync({ pa: 4, pb: 6, max: 36, labelA: '紅線 每 4 分', labelB: '藍線 每 6 分' }),
          },
          {
            type: 'callout', icon: '🔑', title: '公倍數',
            text: '紅線在 4、8、12、16… 發車，藍線在 6、12、18、24… 發車。兩排記號第一次對齊在第 12 分鐘。12 同時是 4 的倍數和 6 的倍數，這種數叫「公倍數」，而第一次遇到的 12 就是「最小公倍數」。',
          },
        ],
      },

      /* ── 5. 找公倍數 ─────────────────────────── */
      {
        heading: '用方格找公倍數',
        blocks: [
          { type: 'text', text: '一樣用方格看：4 的倍數和 6 的倍數，重疊的就是公倍數。' },
          { type: 'component', build: () => new CommonGrid({ a: 4, b: 6, max: 36, mode: 'multiple' }) },
          {
            type: 'callout', icon: '♾️', title: '注意',
            text: '公倍數有無限多個（12、24、36、48…），所以我們只關心「最小」的那一個。公因數則相反，個數有限，我們關心「最大」的那一個。',
          },
          { type: 'text', text: '換你點：把 40 以內、6 和 10 的公倍數全部找出來。' },
          { type: 'component', build: () => new CommonGrid({ a: 6, b: 10, max: 40, mode: 'multiple', interactive: true }) },
        ],
      },

      /* ── 6. 判斷該用哪一個 ───────────────────── */
      {
        heading: '最重要的一步：什麼時候用哪一個？',
        blocks: [
          {
            type: 'text',
            text: '很多人算得出來，卻在應用題選錯。判斷的關鍵在題目問的是「切開分掉」還是「重複再遇到」。',
          },
          {
            type: 'callout', icon: '🔽', title: '用最大公因數',
            text: '題目在「把東西平分、切成一樣大」——分組、切割、包裝。答案會比原來的數小。關鍵字：最多幾人一組、最大的正方形、平分成幾份。',
          },
          {
            type: 'callout', icon: '🔼', title: '用最小公倍數',
            text: '題目在「重複發生、下次再相遇」——同時發車、同時亮燈、排成整齊的長方形。答案會比原來的數大。關鍵字：至少要幾個、下一次同時、最少需要。',
          },
          { type: 'text', text: '把下面的題目放進正確的籃子：' },
          {
            type: 'component',
            build: () => new SortBuckets({
              wide: true,                       // 卡片是整句應用題，不是單一數字
              buckets: [
                { id: 'gcd', label: '🔽 用最大公因數' },
                { id: 'lcm', label: '🔼 用最小公倍數' },
              ],
              items: [
                { text: '把 24 顆糖和 36 片餅乾平分給小朋友，最多可以分給幾人？',
                  bucket: 'gcd', why: '在「平分」，而且要「最多幾人」——答案比原數小，用最大公因數。' },
                { text: '兩個燈號分別每 8 秒、12 秒閃一次，下次同時閃是幾秒後？',
                  bucket: 'lcm', why: '在問「下次同時」——重複發生的問題，用最小公倍數。' },
                { text: '一塊 18 公分 × 24 公分的紙，要剪成一樣大的正方形，正方形邊長最大幾公分？',
                  bucket: 'gcd', why: '在「切割」成一樣大，求「最大」邊長——用最大公因數。' },
                { text: '用長 6 公分、寬 9 公分的磁磚拼成正方形，最小的正方形邊長是多少？',
                  bucket: 'lcm', why: '要一直拼下去直到湊成正方形——重複疊加，用最小公倍數。' },
              ],
            }),
          },
        ],
      },

      /* ── 7. 概念檢查 ─────────────────────────── */
      {
        heading: '概念檢查',
        blocks: [
          { type: 'text', text: '六題小測驗，前三題練計算，後三題練判斷。' },
          {
            type: 'component',
            build: () => new ChoiceQuiz({
              questions: [
                {
                  question: '8 和 12 的最大公因數是多少？',
                  hint: '先各自列出因數：8 → 1、2、4、8；12 → 1、2、3、4、6、12。',
                  options: ['2', '4', '6', '24'],
                  answer: 1,
                  explanation: '公因數是 1、2、4，最大的是 4。（24 是它們的最小公倍數，不要混在一起。）',
                },
                {
                  question: '6 和 8 的最小公倍數是多少？',
                  hint: '6 的倍數：6、12、18、24…；8 的倍數：8、16、24…',
                  options: ['2', '14', '24', '48'],
                  answer: 2,
                  explanation: '第一個同時出現的是 24，所以最小公倍數是 24。48 也是公倍數，但不是最小的。',
                },
                {
                  question: '下面哪一組數字的最大公因數是 1？',
                  hint: '最大公因數是 1，代表除了 1 以外沒有共同的因數。',
                  options: ['6 和 9', '7 和 9', '10 和 15', '12 和 18'],
                  answer: 1,
                  explanation: '7 的因數只有 1 和 7，9 的因數是 1、3、9，共同的只有 1。這種兩數叫「互質」。',
                },
                {
                  question: '有 30 支鉛筆和 45 本筆記本，要平分給同學，每人拿到的一樣多且剛好分完，最多可以分給幾人？',
                  hint: '「平分」而且問「最多幾人」。',
                  options: ['5 人', '15 人', '90 人', '3 人'],
                  answer: 1,
                  explanation: '30 和 45 的最大公因數是 15，所以最多分給 15 人（每人 2 支筆、3 本本子）。',
                },
                {
                  question: '兩艘船，一艘每 4 天進港一次，一艘每 6 天進港一次。今天同時進港，下次同時進港是幾天後？',
                  hint: '「下次同時」。',
                  options: ['2 天', '10 天', '12 天', '24 天'],
                  answer: 2,
                  explanation: '4 和 6 的最小公倍數是 12，所以 12 天後會再度同時進港。',
                },
                {
                  question: '關於公因數和公倍數，下面哪一句是對的？',
                  options: [
                    '公因數有無限多個',
                    '最小公倍數一定比兩個數都小',
                    '1 一定是任何兩個數的公因數',
                    '兩個數的最大公因數一定是 1',
                  ],
                  answer: 2,
                  explanation: '任何數除以 1 都整除，所以 1 一定是公因數。公因數個數有限、公倍數才無限；最小公倍數不會小於原來的數；最大公因數是 1 只有互質時才成立。',
                },
              ],
            }),
          },
        ],
      },
    ],
  };

  window.G5_UNITS = window.G5_UNITS || {};
  window.G5_UNITS[unit.id] = unit;
})();
